export default function ({ native, cred, nonNative, categories, spreadsheetId, folders, pricing }) {
  const types = [
      "Single Integration Native",
      "Single Integration Cred-only",
      "Single Integration Non-native",
      "Categories",
    ],
    lists = [native, cred, nonNative, categories];
  if (
    !spreadsheetId ||
    !pricing ||
    !Array.isArray(folders) ||
    folders.length !== 4 ||
    folders.some((x) => !x)
  )
    throw Error("Configure spreadsheet, four folders and reviewed pricing");
  const jobs = [];
  for (let n = 0; n < 4; n++) {
    const rows = lists[n];
    if (!Array.isArray(rows) || !Array.isArray(rows[0]))
      throw Error("Missing sheet header: " + types[n]);
    const head = rows[0],
      key = n === 3 ? "Category name" : "displayName",
      nameCol = head.indexOf(key),
      statusCol = head.indexOf("status");
    if (
      nameCol < 0 ||
      statusCol < 0 ||
      head.lastIndexOf(key) !== nameCol ||
      head.lastIndexOf("status") !== statusCol
    )
      throw Error("Missing or duplicate required sheet header");
    let k = statusCol + 1,
      col = "";
    while (k) {
      k--;
      col = String.fromCharCode(65 + (k % 26)) + col;
      k = Math.floor(k / 26);
    }
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      if (!Array.isArray(row)) throw Error("Invalid sheet row");
      if (String(row[statusCol] ?? "") !== "") continue;
      const name = String(row[nameCol] ?? "").trim();
      if (!name) {
        if (row.some((x) => String(x ?? "").trim())) throw Error("Unprocessed row missing name");
        continue;
      }
      jobs.push({
        name,
        kind: types[n],
        sheet: types[n],
        row: i + 1,
        statusColumn: col,
        spreadsheetId,
        folderId: folders[n],
        pricing,
      });
    }
  }
  return { jobs };
}

