export default async function ({ job }, ctx) {
  const key = ["faq", job.spreadsheetId, job.sheet, job.row].join(":"),
    s = await ctx.state.get(key);
  if (s?.status === "creating" || s?.status === "updating")
    throw Error("Inspect Drive and sheet before clearing pending checkpoint");
  if (s?.status === "done") return { key, skip: true, created: true };
  if (s?.status === "created") return { key, skip: false, created: true };
  await ctx.state.set(key, { status: "creating" });
  return { key, skip: false, created: false };
}

