import { Buffer } from "node:buffer";
export default function ({ job, result }) {
  if (
    !result ||
    ["setup", "permissions", "combine", "uses"].some(
      (x) => typeof result[x] !== "string" || !result[x].trim(),
    )
  )
    throw Error("Incomplete FAQ");
  const name = job.name,
    questions = [
      {
        question:
          job.kind === "Categories"
            ? `What types of ${name} tools can I integrate with n8n?`
            : `How can I set up ${name} integration in n8n?`,
        answer: result.setup,
      },
      {
        question: `What permissions or credentials may be needed for ${name}?`,
        answer: result.permissions,
      },
      {
        question: `Can I combine ${name} with other apps in n8n workflows?`,
        answer: result.combine,
      },
      { question: `What are common use cases for ${name} integrations?`, answer: result.uses },
      { question: `How does n8n pricing affect ${name} workflows?`, answer: job.pricing },
    ];
  return {
    name: name + "-faq.json",
    mimeType: "application/json",
    contentBase64: Buffer.from(JSON.stringify({ name, questions }, null, 2), "utf8").toString(
      "base64",
    ),
  };
}

