export default async function ({ key }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.status !== "created" || !s.fileId) throw Error("Drive file not confirmed");
  await ctx.state.set(key, { ...s, status: "updating" });
  return { ok: true };
}

